std::string feed(const std::string& viewer){St q("SELECT p.id,u.username,p.content,p.created_at,(SELECT COUNT(*) FROM likes l WHERE l.post_id=p.id),COALESCE(p.image_data,'') FROM posts p JOIN users u ON p.user_id=u.id WHERE NOT EXISTS (SELECT 1 FROM blocks b JOIN users me ON me.id=b.blocker_id WHERE me.username=? AND b.blocked_id=u.id) AND NOT EXISTS (SELECT 1 FROM blocks b JOIN users me ON me.id=b.blocked_id WHERE me.username=? AND b.blocker_id=u.id) ORDER BY p.id DESC LIMIT 100");q.bind(1,viewer);q.bind(2,viewer);std::string out="[";bool first=true;while(q.next()){if(!first)out+=",";first=false;out+="{\"id\":"+std::to_string(q.num(0))+",\"author\":\""+escape(q.str(1))+"\",\"content\":\""+escape(q.str(2))+"\",\"date\":\""+escape(q.str(3))+"\",\"likes\":"+std::to_string(q.num(4))+",\"image\":\""+escape(q.str(5))+"\"}";}return out+"]";}
