if(path=="/api/login"&&method=="POST"){auto u=field(body,"username"),p=field(body,"password");St q("SELECT id,salt,passhash FROM users WHERE username=?");q.bind(1,u);if(!q.next()||!nexus::security::constantTimeEqual(hashPassword(p,q.str(1)),q.str(2))){code=401;return "{\"error\":\"Invalid credentials\"}";}auto t=randomHex();St ins("INSERT INTO sessions(token,user_id) VALUES(?,?)");ins.bind(1,t);ins.bind(2,q.num(0));sqlite3_step(ins.p);return "{\"token\":\""+t+"\",\"username\":\""+escape(u)+"\"}";}
