// v10 account security: current password required, all existing sessions revoked.
if(path=="/api/account/change-password"&&method=="POST"){
 auto oldPass=field(body,"currentPassword"),newPass=field(body,"newPassword");
 if(newPass.size()<12||newPass.size()>128||oldPass.empty()){code=400;return "{\"error\":\"New password must be 12-128 characters\"}";}
 St current("SELECT id,salt,passhash FROM users WHERE username=?");current.bind(1,username);
 if(!current.next()||!nexus::security::constantTimeEqual(hashPassword(oldPass,current.str(1)),current.str(2))){code=403;return "{\"error\":\"Current password is incorrect\"}";}
 auto salt=randomHex(16),hashed=hashPassword(newPass,salt);
 if(hashed.empty()){code=500;return "{\"error\":\"Hashing failed\"}";}
 sql("BEGIN IMMEDIATE");
 St update("UPDATE users SET salt=?,passhash=? WHERE id=?");update.bind(1,salt);update.bind(2,hashed);update.bind(3,current.num(0));
 if(sqlite3_step(update.p)!=SQLITE_DONE){sql("ROLLBACK");code=500;return "{\"error\":\"Password update failed\"}";}
 St revoke("DELETE FROM sessions WHERE user_id=?");revoke.bind(1,current.num(0));
 if(sqlite3_step(revoke.p)!=SQLITE_DONE){sql("ROLLBACK");code=500;return "{\"error\":\"Session revocation failed\"}";}
 sql("COMMIT");return "{\"ok\":true,\"sessionsRevoked\":true}";
}
